contract InvMutTest {
    C c;
    constructor() { c = new C(address(this), 0); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // We will try to exercise play() from this contract and assert a general invariant:
    // If play() does not revert when called, then (1) this contract is no longer recorded as having a wager,
    // and (2) winnersPot() equals address(c).balance / 2 and thus is <= address(c).balance.
    // Inputs: amount to send when wagering (must match c.currentBetLimit to stand a chance) and a flag to attempt opening the contract.
    function run(uint256 wagerAmount, bool tryOpen) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (wagerAmount)); require(wagerAmount <= 1000000000000000000000000000000);
        require(address(this).balance >= wagerAmount, "insufficient balance for wager");

        // Optionally attempt to open the contract to public; may revert if not owner.
        c.OpenToThePublic(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            // ignore failure
        } else {
            // opened ok
        }

        // Read current bet limit and whether we already are recorded (should be false initially)
        uint256 beforeLimit = c.currentBetLimit(); if (__ESBMC_reverted()) return;
        bool beforeRecorded = c.hasPlayerWagered(address(this)); if (__ESBMC_reverted()) return;

        // Attempt to place a wager sending wagerAmount. Catch revert.
        bool wagerReverted;
        c.wager{value: wagerAmount}(); bool __rev1 = __ESBMC_reverted(); if (__rev1) {
            wagerReverted = true;
        } else {
            wagerReverted = false;
        }

        // Now attempt to call play(). It may revert; capture that.
        bool playReverted;
        c.play(); bool __rev2 = __ESBMC_reverted(); if (__rev2) {
            playReverted = true;
        } else {
            playReverted = false;
        }

        // Observe public views after calls
        bool afterRecorded = c.hasPlayerWagered(address(this)); if (__ESBMC_reverted()) return;
        uint256 pot = c.winnersPot(); if (__ESBMC_reverted()) return;
        uint256 cBal = address(c).balance;

        // General rule asserted:
        // If play() did not revert, then the caller must no longer be recorded as having a wager,
        // and winnersPot() must equal address(c).balance / 2 (so it's <= balance).
        assert(playReverted || (afterRecorded == false && pot == (cBal / 2)));
    }

    // Allow receiving Ether so the test contract can fund wagers
    receive() external payable {}
}

