    }

    function _run(uint256 wagerAmount, bool tryOpen) internal {
        wagerAmount = bound(wagerAmount, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= wagerAmount);
        try c.OpenToThePublic() {
            // opened ok
        } catch {
            // ignore failure
        }
        uint256 beforeLimit;
        try c.currentBetLimit() returns (uint256 __r) { beforeLimit = __r; } catch { return; }
        bool beforeRecorded;
        try c.hasPlayerWagered(address(this)) returns (bool __r) { beforeRecorded = __r; } catch { return; }
        bool wagerReverted;
        try c.wager{value: wagerAmount}() {
            wagerReverted = false;
        } catch {
            wagerReverted = true;
        }
        bool playReverted;
        try c.play() {
            playReverted = false;
        } catch {
            playReverted = true;
        }
        bool afterRecorded;
        try c.hasPlayerWagered(address(this)) returns (bool __r) { afterRecorded = __r; } catch { return; }
