        try c.winnersPot() returns (uint256 __r) { pot = __r; } catch { return; }
        uint256 cBal = address(c).balance;
        assertTrue(playReverted || (afterRecorded == false && pot == (cBal / 2)));
    }

    function testFuzz_run(uint256 wagerAmount, bool tryOpen) public {
        _run(wagerAmount, tryOpen);
    }

    receive() external payable {}
